"""Small, self-contained YAML/JSON reader and message type checker.

The command interface uses a YAML scalar or a one-entry mapping to represent a
message. Positions are retained so diagnostics can point back to the input.
"""
import json
import re
import math
from dataclasses import dataclass


def json_text(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'), allow_nan=False)


def debug_string(s):
    out = '"'
    esc = {'\\': '\\\\', '"': '\\"', '\n': '\\n', '\r': '\\r', '\t': '\\t', '\0': '\\0'}
    for c in str(s):
        if c in esc:
            out += esc[c]
        elif ord(c) < 32 or ord(c) == 127:
            out += '\\u{' + format(ord(c), 'x') + '}'
        else:
            out += c
    return out + '"'


class FormatError(Exception):
    pass


@dataclass
class YNode:
    value: object
    pos: int = 0
    end: int = 0
    children: object = None
    raw: str = ''
    quoted: bool = False


class Yaml:
    def __init__(self, text, json_mode=False):
        self.text = text
        self.n = len(text)
        self.i = 0
        self.anchors = {}
        self.json_mode = json_mode

    def where(self, pos):
        line = self.text.count('\n', 0, pos) + 1
        last = self.text.rfind('\n', 0, pos)
        return line, pos - last

    def fail(self, msg, pos=None, context=''):
        line, col = self.where(self.i if pos is None else pos)
        suffix = f' at line {line} column {col}'
        if context:
            suffix += ', while ' + context
        raise FormatError(msg + suffix)

    def skip(self, multiline=True):
        while self.i < self.n:
            if self.text[self.i] in (' \t\r\n' if multiline else ' \t\r'):
                self.i += 1
            elif self.text[self.i] == '#':
                p = self.text.find('\n', self.i)
                self.i = self.n if p < 0 else p
                if not multiline:
                    break
            else:
                break

    def parse(self):
        self.skip()
        if self.text.startswith('---', self.i) and (self.i + 3 == self.n or self.text[self.i+3].isspace()):
            self.i += 3
            self.skip()
        start = self.i
        if self.i >= self.n:
            return YNode(None, start, start, raw='')
        node = self.block(self.where(self.i)[1] - 1)
        self.skip()
        if self.text.startswith('...', self.i):
            self.i += 3
            self.skip()
        if self.text.startswith('---', self.i):
            raise FormatError('deserializing from YAML containing more than one document is not supported')
        if self.i < self.n:
            self.fail('did not find expected key', context='parsing a block mapping')
        return node

    def indent(self, p=None):
        p = self.i if p is None else p
        line = self.text.rfind('\n', 0, p) + 1
        c = line
        while c < self.n and self.text[c] == ' ':
            c += 1
        return c - line

    def line_end(self, p=None):
        p = self.i if p is None else p
        k = self.text.find('\n', p)
        return self.n if k == -1 else k

    def map_colon(self, start, end):
        quote = None
        depth = 0
        i = start
        while i < end:
            c = self.text[i]
            if quote:
                if c == '\\' and quote == '"':
                    i += 1
                elif c == quote:
                    if quote == "'" and i + 1 < end and self.text[i+1] == "'":
                        i += 1
                    else:
                        quote = None
            elif c in "'\"":
                quote = c
            elif c in '[{':
                depth += 1
            elif c in ']}':
                depth -= 1
            elif c == '#' and (i == start or self.text[i-1].isspace()):
                return None
            elif c == ':' and depth == 0 and (i + 1 == end or self.text[i+1].isspace()):
                return i
            i += 1
        return None

    def block(self, indent):
        start = self.i
        seq = self.text.startswith('- ', self.i) or self.text[self.i:self.line_end()].strip() == '-'
        colon = self.map_colon(self.i, self.line_end())
        if not seq and colon is None:
            return self.scalar(False)
        if seq:
            values, children = [], []
            while self.i < self.n and self.indent() == indent and (self.text.startswith('- ', self.i) or self.text[self.i:self.line_end()].strip() == '-'):
                self.i += 1
                self.skip(False)
                if self.i < self.n and self.text[self.i] != '\n':
                    item = self.block(self.where(self.i)[1]-1)
                else:
                    self.skip()
                    item = self.block(self.indent()) if self.i < self.n and self.indent() > indent else YNode(None, self.i, self.i)
                values.append(item.value)
                children.append(item)
                self.skip()
            return YNode(values, start, self.i, children, self.text[start:self.i])
        values, children = {}, {}
        while self.i < self.n:
            line_start = self.i
            colon = self.map_colon(self.i, self.line_end())
            if colon is None:
                break
            rawkey = self.text[self.i:colon].strip()
            keypos = self.i
            keynode = Yaml(rawkey).parse()
            key = keynode.value
            if not isinstance(key, (str, int, bool)) and key is not None:
                self.fail('invalid type: map, expected a scalar key', keypos)
            if key is None:
                key = 'null'
            if not isinstance(key, str):
                key = str(key).lower() if isinstance(key, bool) else str(key)
            kn = YNode(key, keypos, colon, raw=rawkey, quoted=keynode.quoted)
            self.i = colon + 1
            self.skip(False)
            if self.i < self.n and self.text[self.i] != '\n':
                val = self.scalar(False)
            else:
                self.skip()
                ni = self.indent()
                if self.i < self.n and (ni > indent or (ni == indent and self.text.startswith('- ', self.i))):
                    val = self.block(ni)
                else:
                    val = YNode(None, colon + 1, colon + 1)
            if key in values:
                self.fail(f'duplicate entry with key "{key}"', keypos)
            values[key] = val.value
            children[key] = (kn, val)
            before = self.i
            self.skip()
            if self.i >= self.n or self.indent() != indent or self.text.startswith(('---', '...'), self.i):
                break
            if self.map_colon(self.i, self.line_end()) is None:
                if self.i == before:
                    break
                self.fail('could not find expected \':\'', self.i, 'scanning a simple key')
        return YNode(values, start, self.i, children, self.text[start:self.i])

    def scalar(self, flow=False, key=False):
        self.skip(flow)
        start = self.i
        if self.i >= self.n:
            return YNode(None, start, start)
        c = self.text[self.i]
        if c in '[{':
            ismap = c == '{'
            close = '}' if ismap else ']'
            self.i += 1
            self.skip()
            vals = {} if ismap else []
            children = {} if ismap else []
            while self.i < self.n and self.text[self.i] != close:
                if ismap:
                    kn = self.scalar(True, True)
                    kval = kn.value
                    if not isinstance(kval, str):
                        kval = 'null' if kval is None else str(kval).lower() if isinstance(kval, bool) else str(kval)
                    self.skip()
                    if self.i < self.n and self.text[self.i] == ':':
                        self.i += 1
                        self.skip()
                        if self.i < self.n and self.text[self.i] in ',}':
                            val = YNode(None, self.i, self.i)
                        else:
                            val = self.scalar(True)
                    else:
                        val = YNode(None, self.i, self.i)
                    if kval in vals:
                        self.fail(f'duplicate entry with key "{kval}"', kn.pos)
                    vals[kval] = val.value
                    children[kval] = (kn, val)
                else:
                    val = self.scalar(True)
                    vals.append(val.value)
                    children.append(val)
                self.skip()
                if self.i < self.n and self.text[self.i] == ',':
                    self.i += 1
                    self.skip()
                elif self.i < self.n and self.text[self.i] == close:
                    break
                else:
                    self.fail("did not find expected ',' or '"+close+"'", context='parsing a flow '+('mapping' if ismap else 'sequence'))
            if self.i >= self.n:
                # The parser reports an implicit next line at an unterminated flow.
                if not self.text.endswith('\n'):
                    self.text += '\n'; self.n += 1; self.i = self.n
                self.fail('did not find expected node content', context='parsing a flow node')
            self.i += 1
            return YNode(vals, start, self.i, children, self.text[start:self.i])
        if c in "'\"":
            q = c
            self.i += 1
            result = ''
            while self.i < self.n:
                ch = self.text[self.i]
                self.i += 1
                if ch == q:
                    if q == "'" and self.i < self.n and self.text[self.i] == q:
                        self.i += 1
                        result += q
                        continue
                    return YNode(result, start, self.i, raw=self.text[start:self.i], quoted=True)
                if ch == '\\' and q == '"':
                    if self.i >= self.n:
                        break
                    e = self.text[self.i]
                    self.i += 1
                    escapes = {'0':'\0','a':'\a','b':'\b','t':'\t','n':'\n','v':'\v','f':'\f','r':'\r','e':'\x1b',' ':' ','"':'"','/':'/','\\':'\\','N':'\x85','_':'\xa0','L':'\u2028','P':'\u2029'}
                    if e in escapes:
                        result += escapes[e]
                    elif e in 'xuU':
                        count = {'x':2,'u':4,'U':8}[e]
                        try:
                            result += chr(int(self.text[self.i:self.i+count],16))
                            self.i += count
                        except (ValueError, OverflowError):
                            self.fail('did not find expected hexdecimal number', context='parsing a quoted scalar')
                    elif e == '\n':
                        self.skip()
                    else:
                        self.fail('found unknown escape character', self.i-1, 'parsing a quoted scalar')
