        if not flow and c in '|>':
            kind = c
            parent_indent = self.indent()
            line = self.text[self.i:self.line_end()]
            strip = '-' in line
            keep = '+' in line
            self.i = self.line_end()
            if self.i < self.n:
                self.i += 1
            pieces = []
            common = None
            while self.i < self.n:
                p = self.i
                end = self.line_end()
                ln = self.text[p:end]
                ind = len(ln) - len(ln.lstrip(' '))
                if ln.strip() and ind <= parent_indent:
                    break
                if common is None and ln.strip():
                    common = ind
                pieces.append(ln[common or ind:])
                self.i = end + (end < self.n)
            if kind == '|':
                text = '\n'.join(pieces)
            else:
                text = ''
                for j, ln in enumerate(pieces):
                    if j: text += '\n' if not ln or not pieces[j-1] else ' '
                    text += ln
            text = text.rstrip('\n') + ('' if strip else '\n')
            return YNode(text, start, self.i, raw=self.text[start:self.i])
        if c == '*':
            self.i += 1
            m = re.match(r'[\w-]+', self.text[self.i:])
            name = m.group(0) if m else ''
            self.i += len(name)
            if name not in self.anchors:
                self.fail('unknown anchor', start)
            val = self.anchors[name]
            return YNode(val.value, start, self.i, val.children, val.raw)
        if c == '&':
            self.i += 1
            m = re.match(r'[\w-]+', self.text[self.i:]); name = m.group(0) if m else ''
            self.i += len(name); self.skip()
            val = self.scalar(flow)
            self.anchors[name] = val
            return val
        if c == '!':
            end = self.i
            while end < self.n and not self.text[end].isspace(): end += 1
            tag = self.text[self.i:end]
            self.i = end; self.skip()
            val = self.scalar(flow)
            if tag in ('!!str', '!<tag:yaml.org,2002:str>'):
                return YNode(val.raw, start, self.i, quoted=True, raw=val.raw)
