            kn = YNode(tag,start,end,raw=tag)
            return YNode({tag:val.value},start,self.i,{tag:(kn,val)},self.text[start:self.i])
        if c == '%':
            self.fail('could not find expected directive name', start+1,'scanning a directive')
        if c in '@`':
            self.fail('found character that cannot start any token', start, 'scanning for the next token')
        while self.i < self.n:
            ch = self.text[self.i]
            if ch in '\r\n': break
            if flow and ch in ',]}': break
            if ch == ':' and (key or self.i+1 == self.n or self.text[self.i+1].isspace() or (flow and self.text[self.i+1] in ',]}')):
                if not key:
                    self.fail('mapping values are not allowed in this context', self.i)
                break
            if ch == '#' and (self.i == start or self.text[self.i-1].isspace()): break
            self.i += 1
        raw = self.text[start:self.i].rstrip()
        end = start + len(raw)
        val = raw
        low = raw.lower()
        if raw == '' or low in ('null','~'):
            val = None
        elif raw in ('true','True','TRUE','false','False','FALSE'):
            val = low == 'true'
        elif re.fullmatch(r'[+-]?(?:0|[1-9][0-9]*|0x[0-9a-fA-F]+|0o[0-7]+|0b[01]+)', raw):
            try: val = int(raw, 0) if re.match(r'[+-]?0[xob]',raw) else int(raw)
            except ValueError: pass
        elif re.fullmatch(r'[+-]?(?:[0-9]+\.[0-9]*(?:[eE][+-]?[0-9]+)?|[0-9]+[eE][+-]?[0-9]+|\.[0-9]+)',raw):
            try: val = float(raw)
            except ValueError: pass
        elif low in ('.nan','.inf','+.inf','-.inf'):
            val = None
        return YNode(val,start,end,raw=raw)


def load_yaml(text):
    return Yaml(text).parse().value


def dump_yaml(value, indent=0):
    def scalar(v):
        if v is None: return 'null'
        if v is True: return 'true'
        if v is False: return 'false'
        if isinstance(v,(int,float)): return str(v)
        if v == []: return '[]'
        if v == {}: return '{}'
        s = str(v)
        if '\n' in s or any(ord(c)<32 for c in s): return json_text(s)
        if s == '' or s != s.strip() or s[0] in '-?:,[]{}#&*!|>\'"%@`' or ': ' in s or ' #' in s or s.lower() in ('true','false','null','~') or re.fullmatch(r'[+-]?[\d.]+',s):
            return "'" + s.replace("'", "''") + "'"
        return s
    def lines(v, level):
        pad = ' '*level
        if isinstance(v,dict) and v:
            out=[]
            for k,x in v.items():
                key=scalar(str(k))
                if isinstance(x,(dict,list)) and x:
                    out.append(pad+key+':')
                    out.extend(lines(x,level+(0 if isinstance(x,list) else 2)))
                else: out.append(pad+key+': '+scalar(x))
            return out
        if isinstance(v,list) and v:
            out=[]
            for x in v:
                if isinstance(x,(dict,list)) and x:
                    sub=lines(x,level+2)
                    out.append(pad+'- '+sub[0][level+2:]);out.extend(sub[1:])
                else: out.append(pad+'- '+scalar(x))
            return out
        return [pad+scalar(v)]
    return '\n'.join(lines(value,indent))+'\n'


