def format_template(template, args):
    out = ''; i=0; arg=0
    while i<len(template):
        if template[i]!='%': out+=template[i]; i+=1; continue
        pos=i+1; i+=1
        if i>=len(template): raise FormatError('xplr -m: template ended with incomplete placeholder')
        c=template[i];i+=1
        if c=='%':out+='%';continue
        if c not in ('s','q'):
            raise FormatError(f"xplr -m: invalid placeholder '%{c}' at column {pos}, use one of '%s' or '%q', or escape it using '%%'")
        if arg>=len(args):raise FormatError(f'xplr -m: placeholder missing value at column {pos}')
        out += args[arg] if c=='s' else json_text(args[arg]);arg+=1
    if arg<len(args):raise FormatError('xplr -m: too many positional values, not enough positional placeholders')
    return out


def expected_variants(name, variants):
    return 'unknown variant `'+str(name)+'`, expected one of '+', '.join('`'+n+'`' for n in variants)


def validate_message(text, printing=False):
    yaml = Yaml(text)
    # Deserialize directly from YAML, or first normalize to JSON for -m/-M.
    try:
        root = yaml.parse()
    except FormatError as e:
        if not printing and text.lstrip().startswith('['):
            raise FormatError('invalid type: sequence, expected enum ExternalMsg')
        raise FormatError(('xplr -m: yaml: ' if printing else '')+str(e))
    if printing:
        def big(n, path=''):
            if isinstance(n.value,int) and not isinstance(n.value,bool) and not (-2**63<=n.value<=2**64-1):
                typ='u128' if n.value>=0 else 'i128'
                l,c=yaml.where(n.pos)
                raise FormatError(f'xplr -m: yaml: {path+": " if path else ""}invalid type: integer `{n.value}` as {typ}, expected any YAML value at line {l} column {c}')
            if isinstance(n.value,dict):
                for k,(_,v) in n.children.items():big(v,path+'.'+k if path else k)
            elif isinstance(n.value,list):
                for i,v in enumerate(n.children):big(v,path+f'[{i}]')
        big(root)
        text=json_text(root.value)
        yaml=Yaml(text,True)
        root=yaml.parse()
    def pos(n, end=False):
        l,c=yaml.where(n.end if end else n.pos)
        if end: c-=1
        return f' at line {l} column {max(1,c)}'
    def locerr(msg,n,path='', token_end=None):
        if printing:
            if token_end is None:token_end=not isinstance(n.value,(dict,list))
            raise FormatError(msg+pos(n,token_end))
        else:
            prefix=(path+': ') if path else ''
            suffix=pos(n) if n.pos!=0 or path else ''
            raise FormatError(prefix+msg+suffix)
    def typename(n):
        v=n.value
        if v is None:return 'null' if printing else 'unit value'
        if isinstance(v,bool):return 'boolean `'+str(v).lower()+'`'
        if isinstance(v,str):return 'string '+debug_string(v)
        if isinstance(v,int):return f'integer `{v}`'+(' as u128' if v>2**64-1 else ' as i128' if v< -2**63 else '')
        if isinstance(v,float):return f'floating point `{v}`'
        if isinstance(v,list):return 'sequence'
        return 'map'
    def scalar(n,typ,path):
        v=n.value
        if typ=='string':
            if isinstance(v,str):return v
            if not printing and not isinstance(v,(dict,list)):
                if n.raw: return n.raw
                return ''
            locerr('invalid type: '+typename(n)+', expected a string',n,path)
        elif typ=='char':
            if not printing and not isinstance(v,(dict,list)): v=n.raw if not isinstance(v,str) else v
            if not isinstance(v,str): locerr('invalid type: '+typename(n)+', expected a character',n,path)
            if len(v)!=1:locerr('invalid value: string '+debug_string(v)+', expected a character',n,path)
            return v
        elif typ=='int':
            if isinstance(v,int) and not isinstance(v,bool) and 0<=v<=2**64-1:return v
            kind='value' if printing and isinstance(v,int) and not isinstance(v,bool) and v<0 else 'type'
            locerr('invalid '+kind+': '+typename(n)+', expected usize',n,path)
        elif typ=='bool':
            if isinstance(v,bool):return v
            locerr('invalid type: '+typename(n)+', expected a boolean',n,path)
        elif typ=='unit':
            if v is None:return None
            locerr('invalid type: '+typename(n)+', expected unit',n,path)
    def enum(n,names,types,path='',enumname='ExternalMsg'):
        v=n.value
        if isinstance(v,str):
            name=v; inner=None
        elif isinstance(v,dict) and v:
            name=next(iter(v)); kn,inner=n.children[name]
        else:
            if printing:
