        elif typ=='input':result=enum(inner,INPUT_OPS,lambda k:'int' if k=='SetCursor' else 'char' if k=='InsertCharacter' else 'unit',p,'InputOperation')
        elif typ=='filterenum':result=enum(inner,FILTERS,lambda k:'unit',p,'NodeFilter')
        elif typ=='sorterenum':result=enum(inner,SORTERS,lambda k:'unit',p,'NodeSorter')
        else:
