        if isinstance(n.value,list):
            if len(n.value)<len(required):locerr(f'invalid length {len(n.value)}, expected struct {struct} with {len(fields)} elements',n,path)
            entries={k:(YNode(k,n.pos,n.pos),v) for k,v in zip(fields,n.children)}
        else:entries=n.children
