        for k in required:
            if k not in res:locerr(f'missing field `{k}`',n,path,True)
        return res
    def msg_type(k):
        if k in STR_MESSAGES:return 'string'
        if k in INT_MESSAGES:return 'int'
        if k in CALL_MESSAGES:return 'call'
        if k in FILTER_MESSAGES:return 'filter'
        if k in SORTER_MESSAGES:return 'sorter'
        if k in FILTER_ENUM_MESSAGES:return 'filterenum'
        if k in SORTER_ENUM_MESSAGES:return 'sorterenum'
