def format_template(template, args):
    out = ''; i=0; arg=0
    while i<len(template):
        if template[i]!='%': out+=template[i]; i+=1; continue
        pos=i+1; i+=1
        if i>=len(template): raise FormatError('xplr -m: template ended with incomplete placeholder')
        c=template[i];i+=1
        if c=='%':out+='%';continue
        if c not in ('s','q'):
            raise FormatError(f"xplr -m: invalid placeholder '%{c}' at column {pos}, use one of '%s' or '%q', or escape it using '%%'")
        if arg>=len(args):raise FormatError(f'xplr -m: placeholder missing value at column {pos}')
        out += args[arg] if c=='s' else json_text(args[arg]);arg+=1
    if arg<len(args):raise FormatError('xplr -m: too many positional values, not enough positional placeholders')
    return out


