def validate_message(text, printing=False):
    yaml = Yaml(text)
    # Deserialize directly from YAML, or first normalize to JSON for -m/-M.
    try:
        root = yaml.parse()
    except FormatError as e:
        if not printing and text.lstrip().startswith('['):
            raise FormatError('invalid type: sequence, expected enum ExternalMsg')
        raise FormatError(('xplr -m: yaml: ' if printing else '')+str(e))
