        elif arg in ('-V','--version'):opts['version']=True
        elif arg in ('--read0','--write0','-0','--null'):
            if arg in ('--read0','-0','--null'):opts['read0']=True
            if arg in ('--write0','-0','--null'):opts['write0']=True
        elif arg=='--force-focus':opts['force_focus']=True
        elif arg=='--read-only':opts['read_only']=True
        elif arg=='--print-pwd-as-result':opts['print_pwd']=True
        elif arg in ('-c','--config','--vroot'):
