            opts['config' if arg in ('-c','--config') else 'vroot']=path_arg(args[i]);i+=1
        elif arg in ('-C','--extra-config','--on-load'):
            while i<len(args) and not args[i].startswith('-'):
                if arg=='--on-load':opts['messages'].append(validate_message(args[i]))
                else:opts['extra'].append(path_arg(args[i]))
                i+=1
        elif arg in ('-m','--pipe-msg-in','-M','--print-msg-in'):
            if i>=len(args):raise FormatError('usage: xplr '+('-M' if arg in ('-M','--print-msg-in') else '-m')+' FORMAT [ARGUMENT]...')
            text=format_template(args[i],args[i+1:]);msg=validate_message(text,True);output=json_text(msg).encode()
            if arg in ('-M','--print-msg-in'):os.write(1,output)
            elif 'XPLR_PIPE_MSG_IN' not in os.environ:os.write(1,output+b'\n')
            else:
