    else:opts['pwd']=path;opts['focus']=None
    opts['selection']=paths[1:]
    vroot=opts.get('vroot')
    if vroot and not(opts['pwd']==vroot or opts['pwd'].startswith(vroot.rstrip('/')+'/')):
        raise FormatError(debug_string(opts['pwd'])+' is outside of virtual root '+debug_string(vroot))
    return opts


def main():
    app=None;ui=None;fd=None
    try:
